def solve(operations: list[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def solve(numbers: list[float]) -> float:
    mean = sum(numbers) / len(numbers)
    return sum(abs(x - mean) for x in numbers) / len(numbers)

def solve(numbers: list[int], delimiter: int) -> list[int]:
    out = []
    for idx, number in enumerate(numbers):
        if idx:
            out.append(delimiter)
        out.append(number)
    return out

def solve(paren_string: str) -> list[int]:
    out = []
    depth = 0
    best = 0
    for ch in paren_string:
        if ch == '(':
            depth += 1
            best = max(best, depth)
        elif ch == ')':
            depth -= 1
            if depth == 0:
                out.append(best)
                best = 0
    return out

def solve(strings: list[str]) -> str | None:
    if not strings:
        return None
    return max(strings, key=len)

def solve(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return abs(a)

def solve(music_string: str) -> list[int]:
    mapping = {'o': 4, 'o|': 2, '.|': 1}
    return [mapping[token] for token in music_string.split()]

def solve(numbers: str) -> str:
    order = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9}
    return ' '.join(sorted(numbers.split(), key=order.get))

