        a, b = b, a + b
    return a

def solve(a: dict[str, int], b: dict[str, int]) -> dict[str, int]:
    out = dict(a)
    for key, value in b.items():
        out[key] = out.get(key, 0) + value
    return out

def solve(items: list[int]) -> int | None:
    unique = sorted(set(items))
