def solve(items: list[int], k: int) -> list[int]:
    if not items:
        return []
    k %= len(items)
    return items[k:] + items[:k]

def solve(items: list[int], target: int) -> list[int] | None:
    best = None
    best_dist = None
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            dist = abs(items[i] + items[j] - target)
            if best_dist is None or dist < best_dist:
                best = [items[i], items[j]]
                best_dist = dist
    return best

def solve(text: str) -> bool:
    depth = 0
    for ch in text:
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

